        self.keys.len()
    }

    /// Whether the dag has no nodes.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    /// The key of node `ix`.
    #[must_use]
    pub fn key(&self, ix: NodeIx) -> Option<&K> {
        self.keys.get(ix.u())
    }

    /// The node at declaration position `position`, for callers that keep per-node data in declaration order. Valid
    /// only for a dag whose graph had no duplicate declarations, which validation guarantees.
    #[must_use]
    pub fn node_at(&self, position: usize) -> Option<NodeIx> {
        if position < self.len() {
            u32::try_from(position).ok().map(NodeIx)
        } else {
            None
        }
    }

    /// The node with `key`.
    pub fn index_of<Q>(&self, key: &Q) -> Option<NodeIx>
    where
        K: Borrow<Q>,
        Q: Ord + ?Sized,
    {
        lookup(&self.keys, &self.by_key, key).map(NodeIx)
    }

    /// The nodes in topological order: the lexicographically smallest valid order under the dag's [`Order`].
    #[must_use]
    pub fn order(&self) -> &[NodeIx] {
        &self.order
    }

    /// The keys in topological order.
    pub fn keys_in_order(&self) -> impl Iterator<Item = &K> + '_ {
        self.order.iter().filter_map(|&ix| self.key(ix))
    }

    /// The nodes `ix` depends on, in the dag's [`Order`]. Empty for an index the dag does not have.
    #[must_use]
    pub fn prerequisites(&self, ix: NodeIx) -> &[NodeIx] {
        self.prerequisites.of(ix.u())
    }

    /// The nodes that depend on `ix`, in the dag's [`Order`]. Empty for an index the dag does not have.
    #[must_use]
    pub fn dependents(&self, ix: NodeIx) -> &[NodeIx] {
        self.dependents.of(ix.u())
    }

    /// The dag's layers. See [`Layers`].
    #[must_use]
    pub fn layers(&self) -> Layers {
        let n = self.len();
        let mut depth = vec![0usize; n];
        for &ix in self.order.iter() {
            let d = self.prerequisites(ix).iter().filter_map(|p| depth.get(p.u())).max().map_or(0, |d| d + 1);
            if let Some(slot) = depth.get_mut(ix.u()) {
                *slot = d;
            }
        }
        let layers = depth.iter().max().map_or(0, |d| d + 1);
        let mut bounds = vec![0usize; layers + 1];
        for &d in &depth {
            if let Some(b) = bounds.get_mut(d + 1) {
                *b += 1;
            }
        }
        for i in 1..bounds.len() {
            let prev = bounds.get(i - 1).copied().unwrap_or(0);
            if let Some(b) = bounds.get_mut(i) {
                *b += prev;
            }
        }
        let mut cursor = bounds.clone();
        let mut nodes = vec![NodeIx(0); n];
        for &i in self.by_rank.iter() {
            let Some(&d) = depth.get(i as usize) else { continue };
            if let Some(c) = cursor.get_mut(d) {
                if let Some(slot) = nodes.get_mut(*c) {
                    *slot = NodeIx(i);
                }
                *c += 1;
            }
        }
        Layers { nodes, bounds }
    }

    /// The nodes that can start now: those for which `eligible(key)` holds and `satisfied(key)` holds for every
    /// prerequisite, in the dag's [`Order`]. One pass over the graph.
    ///
    /// When `satisfied` holds only for nodes that succeeded, a node behind a failure never becomes ready, so direct
    /// prerequisites are enough.
    pub fn ready<'a, S, R>(&'a self, satisfied: S, eligible: R) -> impl Iterator<Item = NodeIx> + 'a
    where
        S: Fn(&K) -> bool + 'a,
        R: Fn(&K) -> bool + 'a,
    {
        self.by_rank.iter().map(|&i| NodeIx(i)).filter(move |&ix| {
            self.key(ix).is_some_and(&eligible)
                && self.prerequisites(ix).iter().all(|&p| self.key(p).is_some_and(&satisfied))
        })
    }

    /// Every node upstream of `roots`, not including the roots, in the dag's [`Order`].
    #[must_use]
    pub fn ancestors(&self, roots: &[NodeIx]) -> Vec<NodeIx> {
        self.closure(roots, &self.prerequisites)
    }

    /// Every node downstream of `roots`, not including the roots, in the dag's [`Order`].
    #[must_use]
    pub fn descendants(&self, roots: &[NodeIx]) -> Vec<NodeIx> {
        self.closure(roots, &self.dependents)
    }

    fn closure(&self, roots: &[NodeIx], next: &Csr) -> Vec<NodeIx> {
        let n = self.len();
        let mut seen = vec![false; n];
        let mut stack: Vec<NodeIx> = Vec::new();
        for r in roots {
            if let Some(s) = seen.get_mut(r.u()) {
                *s = true;
                stack.push(*r);
            }
        }
        let mut found = Vec::new();
        while let Some(ix) = stack.pop() {
            for &m in next.of(ix.u()) {
                if let Some(s) = seen.get_mut(m.u()) {
                    if !*s {
                        *s = true;
                        found.push(m);
                        stack.push(m);
                    }
                }
            }
        }
        found.sort_unstable_by_key(|ix| self.rank.get(ix.u()).copied().unwrap_or(u32::MAX));
        found
    }

    /// Each node's key with its prerequisites' keys, nodes and prerequisites sorted by key, isolated nodes included:
    /// a canonical form of the structure for callers that hash it with their own hasher.
    pub fn canonical(&self) -> impl Iterator<Item = (&K, Vec<&K>)> + '_ {
        self.by_key.iter().filter_map(move |&i| {
            let key = self.keys.get(i as usize)?;
            let mut prerequisites: Vec<&K> =
                self.prerequisites.of(i as usize).iter().filter_map(|&p| self.key(p)).collect();
            prerequisites.sort_unstable();
            Some((key, prerequisites))
        })
    }
}

    /// 16 lowercase hex digits.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{:016x}", self.0)
    }
}

/// Why a string is not a [`PlanFingerprint`].
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
#[error("a plan fingerprint is 16 hex digits, got {0:?}")]
pub struct ParseFingerprintError(String);

impl std::str::FromStr for PlanFingerprint {
    type Err = ParseFingerprintError;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        if s.len() != 16 {
            return Err(ParseFingerprintError(s.to_string()));
        }
        u64::from_str_radix(s, 16).map(Self).map_err(|_| ParseFingerprintError(s.to_string()))
    }
}

impl TryFrom<String> for PlanFingerprint {
    type Error = ParseFingerprintError;
    fn try_from(s: String) -> Result<Self, Self::Error> {
        s.parse()
    }
}

impl From<PlanFingerprint> for String {
    fn from(fp: PlanFingerprint) -> String {
        fp.to_string()
    }
}

/// FNV-1a, 64-bit.
pub(crate) struct Fnv(u64);

impl Fnv {
    pub(crate) fn new() -> Self {
        Self(0xcbf2_9ce4_8422_2325)
    }
    pub(crate) fn write(&mut self, bytes: &[u8]) {
        for &b in bytes {
            self.0 ^= u64::from(b);
            self.0 = self.0.wrapping_mul(0x0100_0000_01b3);
        }
    }
    pub(crate) fn finish(&self) -> u64 {
        self.0
    }
}

/// A validated, immutable set of steps. Build one with [`Plan::new`]; run it any number of times.
#[derive(Debug)]
pub struct Plan {
    steps: Vec<ExecStep>,
    /// Node indices are declaration positions, so they index `steps` directly.
    dag: Dag<StepId>,
    fingerprint: PlanFingerprint,
}

impl Plan {
    /// Validates `steps` and returns the plan, or every violation at once: duplicate ids, unknown dependencies,
    /// self-dependencies and cycles (found without recursion, so depth is bounded by memory).
    ///
    /// # Errors
    ///
    /// A [`PlanError`] listing every [`PlanViolation`] when the steps do not form a valid graph.
    pub fn new(steps: Vec<ExecStep>) -> Result<Self, PlanError> {
        let mut b = GraphBuilder::<StepId>::with_capacity(steps.len());
        for step in &steps {
            let node = b.node(step.id.clone());
            for dep in &step.depends_on {
                b.depends_on(node, dep.clone(), ());
            }
        }
        let dag = b
            .build(UnknownTargets::Error)
            .validate(Order::Declaration)
            .map_err(|violations| plan_error(&steps, violations))?;
        let fingerprint = fingerprint(&dag);
        Ok(Self { steps, dag, fingerprint })
    }

    /// The dry run: step ids in the order sequential mode dispatches them, which is topological order with ties
    /// broken by declaration order. Nothing runs.
    #[must_use]
    pub fn execution_order(&self) -> Vec<&StepId> {
        self.dag.order().iter().filter_map(|ix| self.steps.get(ix.index())).map(|s| &s.id).collect()
    }

    /// The plan's structural fingerprint.
    #[must_use]
    pub fn fingerprint(&self) -> PlanFingerprint {
        self.fingerprint
    }

    /// The steps, in declaration order.
    #[must_use]
    pub fn steps(&self) -> &[ExecStep] {
        &self.steps
    }

    /// The step with `id`, if any.
    #[must_use]
    pub fn step(&self, id: &StepId) -> Option<&ExecStep> {
        self.dag.index_of(id).and_then(|ix| self.steps.get(ix.index()))
    }

    /// Number of steps.
    #[must_use]
    pub fn len(&self) -> usize {
        self.steps.len()
    }

    /// Whether the plan has no steps.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.steps.is_empty()
    }

    pub(crate) fn index_of(&self, id: &StepId) -> Option<usize> {
        self.dag.index_of(id).map(NodeIx::index)
    }

    pub(crate) fn prerequisites_of(&self, i: usize) -> impl Iterator<Item = usize> + '_ {
        self.node(i).map(|ix| self.dag.prerequisites(ix)).unwrap_or_default().iter().map(|p| p.index())
    }

    pub(crate) fn dependents_of(&self, i: usize) -> impl Iterator<Item = usize> + '_ {
        self.node(i).map(|ix| self.dag.dependents(ix)).unwrap_or_default().iter().map(|d| d.index())
    }

    pub(crate) fn topological_order(&self) -> impl Iterator<Item = usize> + '_ {
        self.dag.order().iter().map(|ix| ix.index())
    }

    fn node(&self, i: usize) -> Option<NodeIx> {
        self.dag.node_at(i)
    }
}

/// Maps michi-graph's violations onto michi's, keeping michi's shape: one `Cycle` listing every step on any cycle,
/// in declaration order.
fn plan_error(steps: &[ExecStep], violations: michi_graph::Violations<StepId>) -> PlanError {
    let mut out = Vec::new();
    let mut on_cycle: Vec<StepId> = Vec::new();
    for v in violations {
        match v {
            Violation::DuplicateNode { key } => out.push(PlanViolation::DuplicateStepId { step_id: key }),
            Violation::UnknownDependency { dependent, prerequisite } => {
                out.push(PlanViolation::UnknownDependency { step_id: dependent, dependency: prerequisite });
            }
            Violation::SelfDependency { key } => out.push(PlanViolation::SelfDependency { step_id: key }),
            Violation::Cycle(cycle) => on_cycle.extend(cycle.members().iter().cloned()),
            _ => out.push(PlanViolation::TooManySteps),
        }
    }
    if !on_cycle.is_empty() {
        let mut position: BTreeMap<&StepId, usize> = BTreeMap::new();
        for (i, step) in steps.iter().enumerate() {
            position.entry(&step.id).or_insert(i);
        }
        on_cycle.sort_by_key(|id| position.get(id).copied().unwrap_or(usize::MAX));
        out.push(PlanViolation::Cycle { step_ids: on_cycle });
    }
    PlanError { violations: out }
}

/// FNV-1a over each step's id and prerequisite ids, both sorted by id.
fn fingerprint(dag: &Dag<StepId>) -> PlanFingerprint {
    let mut h = Fnv::new();
    for (id, deps) in dag.canonical() {
        h.write(id.as_str().as_bytes());
        h.write(&[0x1f]);
        for dep in deps {
            h.write(dep.as_str().as_bytes());
            h.write(&[0x1e]);
        }
        h.write(&[0x1d]);
    }
    PlanFingerprint(h.0)
}

