/// it is caught so it can neither unwind the scheduler (losing the record and dropping running steps) nor stop the
/// run. The caller counts it in [`RunRecord::observer_panics`].
fn observe(opts: &ExecOptions, call: impl FnOnce(&dyn StepObserver)) -> bool {
    let Some(observer) = opts.observer.as_deref() else { return false };
    // AssertUnwindSafe: after a caught panic the scheduler only reads its own state, which the observer cannot
    // touch; whatever state the observer itself left half-updated is its own.
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| call(observer))).is_err()
}

/// The step a failure is attributed to: a skipped step's root cause, or the step itself.
fn root_of(record: &StepRecord) -> StepId {
    record.caused_by.clone().unwrap_or_else(|| record.step_id.clone())
}

/// The outcome of a task that did not return: it panicked, or (only if the set was dropped) it was aborted.
fn harness_outcome(join_err: tokio::task::JoinError, replay: Replay) -> Outcome {
    if join_err.is_panic() {
        let payload = join_err.into_panic();
        let message = payload
            .downcast_ref::<&str>()
            .map(|s| (*s).to_string())
            .or_else(|| payload.downcast_ref::<String>().cloned())
            .unwrap_or_else(|| "non-string panic payload".to_string());
        let error = ExecutionError::Panicked { message };
        return Outcome { status: StepStatus::Panicked, reason: Some(error.to_string()), error: Some(error) };
    }
    classify(ExecutionError::Interrupted { elapsed_ms: 0 }, replay, "task aborted", true)
}

/// Whether the executor may run the step again after `err`: the error must be retryable, and an ambiguous one only
/// for an idempotent step.
fn may_reinvoke(replay: Replay, err: &ExecutionError) -> bool {
    err.is_retryable() && (replay == Replay::Idempotent || err.replay_class() != ReplayClass::Ambiguous)
}

/// One attempt under a timeout, racing cancellation plus the grace period.
async fn attempt_once(
    step: &dyn Step,
    ctx: &StepContext,
    limit: Duration,
    token: &CancellationToken,
    grace: Duration,
) -> Result<(), ExecutionError> {
    let start = Instant::now();
    let attempt = tokio::time::timeout(limit, step.run(ctx));
    let interrupted = async {
        token.cancelled().await;
        tokio::time::sleep(grace).await;
    };
    tokio::select! {
        biased;
        result = attempt => result.unwrap_or(Err(ExecutionError::Timeout { elapsed_ms: millis(limit) })),
        () = interrupted => Err(ExecutionError::Interrupted { elapsed_ms: millis(start.elapsed()) }),
    }
}

/// Admission, the retry loop and classification for one step.
async fn run_step(job: Job) -> Outcome {
    if job.token.is_cancelled() {
        return Outcome {
            status: StepStatus::Skipped(SkipReason::Cancelled),
            error: None,
            reason: Some("run cancelled before the step started".to_string()),
        };
    }
    let guard = match &job.breaker {
        Some((key, breaker)) => match breaker.admit() {
            Ok(admission) => Some(AdmissionGuard::new(Arc::clone(breaker), admission)),
            Err(err) => {
                return Outcome {
                    status: StepStatus::NotRun(NotRunReason::CircuitOpen),
                    reason: Some(format!("circuit breaker {key}: {err}")),
                    error: Some(err),
                }
            }
        },
        None => None,
    };
    let probe = guard.as_ref().is_some_and(AdmissionGuard::is_probe);
    let started = Instant::now();
    // A deadline too far away for the clock to represent is no deadline, rather than an overflow panic.
    let deadline = job.deadline.and_then(|d| started.checked_add(d));
    let mut attempt = 0u32;
    let (err, stop) = loop {
        let ctx =
            StepContext::for_attempt(job.run_id.clone(), job.step_id.clone(), attempt, job.token.clone(), deadline);
        let attempt_start = Instant::now();
        let limit = match deadline {
            Some(d) => {
                job.attempt_timeout.min(d.saturating_duration_since(attempt_start)).max(Duration::from_millis(1))
            }
            None => job.attempt_timeout,
        };
        let result = attempt_once(job.runner.as_ref(), &ctx, limit, &job.token, job.grace).await;
        lock(&job.attempts).push(AttemptRecord {
            attempt,
            class: result.as_ref().err().map(ExecutionError::replay_class),
            error: result.as_ref().err().map(ToString::to_string),
            elapsed: attempt_start.elapsed(),
        });
        let err = match result {
            Ok(()) => {
                if let Some(budget) = &job.budget {
                    lock(budget).deposit();
                }
                if let Some(guard) = guard {
                    guard.complete(true);
                }
                return Outcome { status: StepStatus::Completed, error: None, reason: None };
            }
            Err(err) => err,
        };
        if job.token.is_cancelled() {
            break (err, "run cancelled");
        }
        if !may_reinvoke(job.replay, &err) {
            break (err, "");
        }
        if probe {
            break (err, "a half-open breaker allows one probe attempt");
        }
        let seed = job.jitter_seed.unwrap_or_else(|| derived_jitter_seed(&job.run_id, &job.step_id, attempt));
        let Some(delay) = retry_delay(&job.retry, attempt, seed, err.retry_after()) else {
            break (err, "retries exhausted");
        };
        if deadline.is_some_and(|d| Instant::now().checked_add(delay).is_none_or(|wake| wake >= d)) {
            break (err, "step deadline reached");
        }
        if let Some(budget) = &job.budget {
            if !lock(budget).try_withdraw() {
                break (err, "retry budget exhausted");
            }
        }
        let cancelled = tokio::select! {
            () = tokio::time::sleep(delay) => false,
            () = job.token.cancelled() => true,
        };
        if cancelled {
            break (err, "run cancelled during backoff");
        }
        attempt += 1;
    };
    if let Some(guard) = guard {
        match err.innermost() {
            // Cancellation says nothing about the downstream's health: release a probe, report nothing.
            ExecutionError::Cancelled | ExecutionError::Interrupted { .. } => {}
            // The downstream answered and rejected the request itself: it is up, so this is not a failure.
            ExecutionError::Http { status, .. } if is_client_error(*status) => guard.complete(true),
            _ => guard.complete(false),
        }
    }
    classify(err, job.replay, stop, job.token.is_cancelled())
}

/// Whether an HTTP status is the caller's own mistake (4xx other than 408 Request Timeout and 429 Too Many Requests):
/// proof the downstream is up and answering, so it never counts as a breaker failure. 408 and 429 say the downstream
/// is slow or overloaded, and 5xx says it failed, so those do count.
fn is_client_error(status: u16) -> bool {
    (400..500).contains(&status) && status != 408 && status != 429
}

/// The backoff before retry `attempt + 1`: michi-core's [`next_retry_delay`], except that a server's `retry_after` is
/// honoured in full even past `RetryConfig::max_delay`, which caps only the exponential backoff. The step deadline
/// still bounds it: the caller stops retrying if the wait would end past the deadline.
fn retry_delay(retry: &RetryConfig, attempt: u32, seed: f64, retry_after: Option<Duration>) -> Option<Duration> {
    let backoff = next_retry_delay(retry, attempt, seed, retry_after)?;
    Some(retry_after.map_or(backoff, |hint| backoff.max(ceil_to_millis(hint))))
}

/// `d` rounded up to whole milliseconds, as `next_retry_delay` rounds a hint, so a hint is never shortened.
fn ceil_to_millis(d: Duration) -> Duration {
    let whole = Duration::from_millis(millis(d));
    if whole < d {
        whole.saturating_add(Duration::from_millis(1))
    } else {
        whole
    }
}

/// A jitter seed in `[0, 1)` for one retry, derived from the run id, step id and attempt: steps that fail together
/// back off by different amounts, and the same run always waits the same delays.
fn derived_jitter_seed(run_id: &RunId, step_id: &StepId, attempt: u32) -> f64 {
    let mut h = Fnv::new();
    h.write(run_id.as_str().as_bytes());
    h.write(b":");
    h.write(step_id.as_str().as_bytes());
    h.write(b":");
    h.write(&attempt.to_le_bytes());
    // FNV-1a mixes its last bytes poorly; the splitmix64 finalizer spreads them over every bit.
    let mut z = h.finish();
    z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
    z ^= z >> 31;
    // The top 53 bits as a fraction of 2^53, both exact in an f64.
    #[allow(clippy::cast_precision_loss, reason = "53-bit values fit an f64 mantissa exactly")]
    let fraction = (z >> 11) as f64 / (1u64 << 53) as f64;
    fraction
}

/// The terminal status and final error for a step whose last attempt failed with `err`. `cancelled` says whether the
/// step's cancellation token had fired. A step that returns [`ExecutionError::Cancelled`] while it had not stopped on
/// its own, so it ends `Failed`: a root cause that resume runs again, not a `Skipped(Cancelled)` consequence.
fn classify(err: ExecutionError, replay: Replay, stop: &str, cancelled: bool) -> Outcome {
    let class = err.replay_class();
    let mut stop = stop;
    let (status, error) = match class {
        ReplayClass::Ambiguous if replay == Replay::NotIdempotent => {
            let cause = match err.innermost() {
                ExecutionError::Http { status: 502 | 504, .. } => UnknownCause::Gateway,
                ExecutionError::Interrupted { .. } => UnknownCause::Cancelled,
                ExecutionError::Panicked { .. } => UnknownCause::Interrupted,
                _ => UnknownCause::Timeout,
            };
            let error =
                if err.is_retryable() { ExecutionError::AmbiguousOutcome { source: Box::new(err) } } else { err };
            (StepStatus::OutcomeUnknown(cause), error)
        }
        ReplayClass::NotExecuted => match err.innermost() {
            ExecutionError::CircuitOpen { .. } => (StepStatus::NotRun(NotRunReason::CircuitOpen), err),
            _ if cancelled => (StepStatus::Skipped(SkipReason::Cancelled), err),
            _ => {
                if stop.is_empty() {
                    stop = "the step cancelled itself although the run was not cancelled";
                }
                (StepStatus::Failed, err)
            }
        },
        _ => (StepStatus::Failed, err),
    };
    let reason = if stop.is_empty() { error.to_string() } else { format!("{error}; {stop}") };
    Outcome { status, error: Some(error), reason: Some(reason) }
}

//! Options, the observer, and the `execute`/`resume` entry points.

use std::collections::BTreeMap;
use std::num::NonZeroUsize;
use std::sync::Arc;
use std::time::Duration;

use michi_core::pipeline::{StepStatus, UnknownCause};
use michi_core::resilience::{RetryBudget, RetryConfig};

use crate::scheduler::{self, Initial};
use crate::{
    BreakerRegistry, CancellationToken, ExecutionError, Plan, PlanFingerprint, RunId, RunRecord, StepId, StepRecord,
};

/// How many steps run at once.
#[non_exhaustive]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum Mode {
    /// One step at a time, in [`Plan::execution_order`]. Deterministic.
    #[default]
    Sequential,
    /// Up to `max_concurrency` steps at once. Ready steps are dispatched in declaration order while fewer than the
    /// cap are running.
    Parallel {
        /// The most steps running at once.
        max_concurrency: NonZeroUsize,
    },
}

/// What a step failure does to the rest of the run.
#[non_exhaustive]
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum FailurePolicy {
    /// Skip the failed step's transitive dependents; independent branches keep running.
    #[default]
    SkipDependents,
    /// Stop dispatching and cancel running steps (after the cancellation grace period, their attempts are dropped).
    FailFast,
}

/// Called synchronously from the scheduler loop as steps start and finish, so callers can persist progress and
/// rebuild the run with [`RunRecord::from_parts`] after a crash. A closure `Fn(&RunId, &StepRecord)` implements it
/// (finish events only). Keep it quick: it runs between dispatches.
///
/// A panic in an observer method is caught: the run continues, later events are still delivered, and the panic is
/// counted in [`RunRecord::observer_panics`]. (The process's panic hook still runs, so the default hook prints it.)
pub trait StepObserver: Send + Sync {
    /// A step is about to be dispatched. Persist [`StepRecord::in_flight`] here to make a crash mid-step visible.
    fn on_step_started(&self, run_id: &RunId, step_id: &StepId) {
        let _ = (run_id, step_id);
    }

    /// A step reached its terminal status in this run: ran, was skipped, or (on resume) was carried over.
    fn on_step_finished(&self, run_id: &RunId, record: &StepRecord);
}

impl<F> StepObserver for F
where
    F: Fn(&RunId, &StepRecord) + Send + Sync,
{
    fn on_step_finished(&self, run_id: &RunId, record: &StepRecord) {
        self(run_id, record);
    }
}

/// Options for [`execute`]. Every field has a default; builder methods override them.
#[derive(Clone)]
pub struct ExecOptions {
    pub(crate) mode: Mode,
    pub(crate) failure_policy: FailurePolicy,
    pub(crate) retry: RetryConfig,
    pub(crate) attempt_timeout: Duration,
    pub(crate) step_deadline: Option<Duration>,
    pub(crate) jitter_seed: Option<f64>,
    pub(crate) cancellation: CancellationToken,
    pub(crate) cancel_grace: Duration,
    pub(crate) retry_budget: Option<RetryBudget>,
    pub(crate) breakers: Option<Arc<BreakerRegistry>>,
    pub(crate) observer: Option<Arc<dyn StepObserver>>,
}

impl Default for ExecOptions {
    fn default() -> Self {
        Self {
            mode: Mode::Sequential,
            failure_policy: FailurePolicy::SkipDependents,
            retry: RetryConfig::default(),
            attempt_timeout: Duration::from_secs(30),
            step_deadline: None,
            jitter_seed: None,
            cancellation: CancellationToken::new(),
            cancel_grace: Duration::from_secs(5),
            retry_budget: Some(RetryBudget::default()),
            breakers: None,
            observer: None,
        }
    }
}

impl std::fmt::Debug for ExecOptions {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("ExecOptions")
            .field("mode", &self.mode)
            .field("failure_policy", &self.failure_policy)
            .field("retry", &self.retry)
            .field("attempt_timeout", &self.attempt_timeout)
            .field("step_deadline", &self.step_deadline)
            .field("jitter_seed", &self.jitter_seed)
            .field("cancel_grace", &self.cancel_grace)
            .field("retry_budget", &self.retry_budget)
            .field("breakers", &self.breakers.is_some())
            .field("observer", &self.observer.is_some())
            .finish_non_exhaustive()
    }
}

impl ExecOptions {
    /// The defaults: sequential, skip dependents, `RetryConfig::default()`, 30 s per attempt, no step deadline,
    /// jitter seeded per run, step and attempt, 5 s cancellation grace, `RetryBudget::default()`, no breakers, no observer.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Sequential or parallel scheduling.
    #[must_use]
    pub fn mode(mut self, mode: Mode) -> Self {
        self.mode = mode;
        self
    }

    /// What a failure does to the rest of the run.
    #[must_use]
    pub fn failure_policy(mut self, policy: FailurePolicy) -> Self {
        self.failure_policy = policy;
        self
    }

    /// The retry policy for steps without their own.
    #[must_use]
    pub fn retry(mut self, retry: RetryConfig) -> Self {
        self.retry = retry;
        self
    }

    /// The per-attempt timeout for steps without their own. Zero is floored to 1 ms.
    #[must_use]
    pub fn attempt_timeout(mut self, timeout: Duration) -> Self {
        self.attempt_timeout = timeout;
        self
    }

    /// A total time bound per step across all attempts and backoff, for steps without their own. A deadline too far
    /// away for the clock to represent (such as `Duration::MAX`) means no deadline.
    #[must_use]
    pub fn step_deadline(mut self, deadline: Duration) -> Self {
        self.step_deadline = Some(deadline);
        self
    }

    /// A fixed jitter seed in `[0, 1]`, passed to `next_retry_delay` for every retry of every step.
    ///
    /// Without one (the default), each retry gets its own seed derived from the run id, step id and attempt number,
    /// so steps that fail together do not retry in lockstep, yet the same run and plan always wait the same delays.
    /// A fixed seed makes every step's backoff identical; use it only when that is what you want (tests, say).
    #[must_use]
    pub fn jitter_seed(mut self, seed: f64) -> Self {
        self.jitter_seed = Some(seed);
        self
    }

    /// The caller's cancellation token. The run uses a child of it.
    #[must_use]
    pub fn cancellation(mut self, token: CancellationToken) -> Self {
        self.cancellation = token;
        self
    }

    /// How long a running attempt may keep going after cancellation before it is dropped.
    #[must_use]
    pub fn cancel_grace(mut self, grace: Duration) -> Self {
        self.cancel_grace = grace;
        self
    }

    /// The per-run retry budget's starting state.
    #[must_use]
    pub fn retry_budget(mut self, budget: RetryBudget) -> Self {
        self.retry_budget = Some(budget);
        self
    }

    /// Retries are limited only by each step's retry policy.
    #[must_use]
    pub fn no_retry_budget(mut self) -> Self {
        self.retry_budget = None;
        self
    }

    /// The breaker registry. Share one across runs so samples accumulate. Without one, no breaker applies.
    #[must_use]
    pub fn breakers(mut self, registry: Arc<BreakerRegistry>) -> Self {
        self.breakers = Some(registry);
        self
    }

    /// The step observer.
    #[must_use]
    pub fn observer(mut self, observer: Arc<dyn StepObserver>) -> Self {
        self.observer = Some(observer);
        self
    }
}

/// What the caller found when checking a step whose outcome was unknown.
#[non_exhaustive]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Verification {
    /// The effect happened: resume treats the step as `CompletedEarlier`.
    Applied,
    /// The effect did not happen: resume runs the step again.
    NotApplied,
}

/// Options for [`resume`]: the execution options plus the caller's verdicts on steps whose outcome was unknown.
#[derive(Debug, Clone, Default)]
pub struct ResumeOptions {
    pub(crate) exec: ExecOptions,
    pub(crate) verified: BTreeMap<StepId, Verification>,
}

impl ResumeOptions {
    /// Resume with these execution options and no verdicts.
    #[must_use]
    pub fn new(exec: ExecOptions) -> Self {
        Self { exec, verified: BTreeMap::new() }
    }

    /// Records what the caller found for a step that is `OutcomeUnknown`, `Panicked` or `Running` in the prior
    /// record.
    #[must_use]
    pub fn verified(mut self, step_id: StepId, verification: Verification) -> Self {
        self.verified.insert(step_id, verification);
        self
    }
}

/// Why [`resume`] refused to run, or [`RunRecord::from_parts`] refused to rebuild a record.
#[non_exhaustive]
#[derive(Debug, Clone, PartialEq, thiserror::Error)]
pub enum ResumeError {
    /// The plan's structure differs from the plan the record was made with. Start a new run instead.
    #[error("the plan changed since the run started: record fingerprint {record}, plan fingerprint {plan}")]
    FingerprintMismatch {
        /// The record's fingerprint.
        record: PlanFingerprint,
        /// The plan's fingerprint.
        plan: PlanFingerprint,
    },
    /// The record has a step the plan does not.
    #[error("the record has step {step_id}, which the plan does not")]
    UnknownStep {
        /// The step id.
        step_id: StepId,
    },
    /// A verdict was given for a step whose outcome is not in doubt.
    #[error("step {step_id} is {status}, not awaiting verification")]
    NotAwaitingVerification {
        /// The step id.
        step_id: StepId,
        /// Its status label in the prior record, or `missing`.
        status: &'static str,
    },
}

impl From<ResumeError> for michi_core::DomainError {
    fn from(err: ResumeError) -> Self {
        let code = match err {
            ResumeError::FingerprintMismatch { .. } => michi_core::ErrorCode::Conflict,
            ResumeError::UnknownStep { .. } | ResumeError::NotAwaitingVerification { .. } => {
                michi_core::ErrorCode::InvalidInput
            }
        };
        michi_core::DomainError::new(code, err.to_string()).retryable(false)
    }
}

/// Runs `plan` under `run_id` and returns what happened to every step. Never fails: a run that happened is a record.
///
/// Steps run on a `JoinSet` owned by this call, so none outlives it; dropping the returned future aborts them.
pub async fn execute(plan: &Plan, run_id: RunId, opts: &ExecOptions) -> RunRecord {
    let initial = (0..plan.len()).map(|_| Initial::Run).collect();
    scheduler::run(plan, run_id, opts, initial).await
}

/// Continues the run in `prior` under its run id, so idempotency keys stay the same.
///
/// Refuses, before running anything, a plan whose fingerprint differs from the record's, a record naming a step the
/// plan lacks, and a verdict for a step that is not awaiting verification. Then: `Completed` and `CompletedEarlier`
/// steps become `CompletedEarlier` and are not run; `Failed`, `Skipped`, `NotRun`, `Pending` and missing steps run
/// again; `OutcomeUnknown`, `Panicked` and `Running` steps run again only if the step is [`crate::Replay::Idempotent`]
/// or the caller verified them as [`Verification::NotApplied`], become `CompletedEarlier` if verified as
/// [`Verification::Applied`], and otherwise keep their prior record (a `Running` one becomes
/// `OutcomeUnknown(Interrupted)`).
///
/// At least once per step: a step can run again if the process stopped after its effect but before its record was
/// saved. Not incremental recomputation: a completed step is not re-run because its inputs changed.
///
/// # Errors

//! Declaring nodes and edges.

use alloc::sync::Arc;
use alloc::vec::Vec;

use crate::graph::{Dangling, Edge, Graph};
use crate::{NodeIx, UnknownTargets};

/// A node declaration, returned by [`GraphBuilder::node`]. Edges hang off the declaration rather than the key, so the
/// edges of a duplicate declaration are dropped with it instead of landing on the first node with that key.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Decl(u32);

/// Collects nodes and edges. [`GraphBuilder::build`] never fails; problems are reported when the graph is validated.
#[derive(Debug, Clone)]
pub struct GraphBuilder<K, E = ()> {
    decls: Vec<K>,
    edges: Vec<(u32, K, E)>,
    overflow: bool,
}

impl<K: Ord + Clone, E: Ord> Default for GraphBuilder<K, E> {
    fn default() -> Self {
        Self::new()
    }
}

impl<K: Ord + Clone, E: Ord> GraphBuilder<K, E> {
    /// An empty builder.
    #[must_use]
    pub fn new() -> Self {
        Self { decls: Vec::new(), edges: Vec::new(), overflow: false }
    }

    /// An empty builder with room for `nodes` declarations.
    #[must_use]
    pub fn with_capacity(nodes: usize) -> Self {
        Self { decls: Vec::with_capacity(nodes), edges: Vec::with_capacity(nodes), overflow: false }
    }

    /// Declares a node. A later declaration reusing a key is reported as [`crate::Violation::DuplicateNode`], and the
    /// edges added to it are dropped.
    pub fn node(&mut self, key: K) -> Decl {
        match u32::try_from(self.decls.len()) {
            Ok(n) if n < u32::MAX => {
                self.decls.push(key);
                Decl(n)
            }
            _ => {
                self.overflow = true;
                Decl(u32::MAX)
            }
        }
    }

    /// Adds an edge: `dependent` depends on the node keyed `prerequisite`, which may be declared before or after it.
    /// Repeating an edge with the same kind has no further effect.
    pub fn depends_on(&mut self, dependent: Decl, prerequisite: K, kind: E) -> &mut Self {
        if (dependent.0 as usize) < self.decls.len() {
            self.edges.push((dependent.0, prerequisite, kind));
        }
        self
    }

    /// Builds the graph, keeping every node and edge it can use and recording the rest: duplicate declarations,
    /// edges to unknown keys (always kept in [`Graph::dangling`]; `unknown` decides whether validation reports them)
    /// and more than `u32::MAX - 1` nodes.
    #[must_use]
    pub fn build(self, unknown: UnknownTargets) -> Graph<K, E> {
        let Self { decls, edges, overflow } = self;

        // Declarations sorted by key, ties by position: the first of each run of equal keys is the node.
        let mut sorted: Vec<u32> = (0..decls.len()).filter_map(|i| u32::try_from(i).ok()).collect();
        sorted.sort_by(|&a, &b| decl(&decls, a).cmp(&decl(&decls, b)).then(a.cmp(&b)));
        let mut is_duplicate = alloc::vec![false; decls.len()];
        for pair in sorted.windows(2) {
            if let [a, b] = *pair {
                if decl(&decls, a) == decl(&decls, b) {
                    if let Some(d) = is_duplicate.get_mut(b as usize) {
                        *d = true;
                    }
                }
            }
        }

        let mut node_of_decl: Vec<Option<u32>> = Vec::with_capacity(decls.len());
        let mut keys: Vec<K> = Vec::with_capacity(decls.len());
        let mut duplicates: Vec<K> = Vec::new();
        for (key, dup) in decls.into_iter().zip(is_duplicate) {
            if dup {
                node_of_decl.push(None);
                duplicates.push(key);
            } else {
                node_of_decl.push(u32::try_from(keys.len()).ok());
                keys.push(key);
            }
        }
        let mut by_key: Vec<u32> = (0..keys.len()).filter_map(|i| u32::try_from(i).ok()).collect();
        by_key.sort_by(|&a, &b| decl(&keys, a).cmp(&decl(&keys, b)));

        let mut resolved: Vec<Edge<E>> = Vec::with_capacity(edges.len());
        let mut dangling: Vec<Dangling<K, E>> = Vec::new();
        for (seq, (d, prerequisite, kind)) in edges.into_iter().enumerate() {
            let Some(dependent) = node_of_decl.get(d as usize).copied().flatten() else { continue };
            match lookup(&keys, &by_key, &prerequisite) {
                Some(p) => resolved.push(Edge { dependent, prerequisite: p, kind, seq }),
                None => dangling.push(Dangling { dependent: NodeIx(dependent), prerequisite, kind, seq }),
            }
        }
        // One edge per (dependent, prerequisite, kind), the first declared; then back to declaration order.
        resolved.sort_by(|a, b| {
            (a.dependent, a.prerequisite, &a.kind, a.seq).cmp(&(b.dependent, b.prerequisite, &b.kind, b.seq))
        });
        resolved.dedup_by(|b, a| a.dependent == b.dependent && a.prerequisite == b.prerequisite && a.kind == b.kind);
        resolved.sort_by_key(|e| e.seq);
        dangling.sort_by(|a, b| {
            (a.dependent, &a.prerequisite, &a.kind, a.seq).cmp(&(b.dependent, &b.prerequisite, &b.kind, b.seq))
        });
        dangling.dedup_by(|b, a| a.dependent == b.dependent && a.prerequisite == b.prerequisite && a.kind == b.kind);
        dangling.sort_by_key(|e| e.seq);

        Graph {
            keys: Arc::from(keys),
            by_key: Arc::from(by_key),
            edges: resolved,
            dangling,
            duplicates,
            unknown,
            overflow,
        }
    }
}

fn decl<K>(keys: &[K], i: u32) -> Option<&K> {
    keys.get(i as usize)
}

/// Binary search of `by_key` (node indices sorted by key) for `key`.
pub(crate) fn lookup<K, Q>(keys: &[K], by_key: &[u32], key: &Q) -> Option<u32>
where
    K: core::borrow::Borrow<Q>,
    Q: Ord + ?Sized,
{
    let pos = by_key
        .binary_search_by(|&i| match keys.get(i as usize) {
            Some(k) => k.borrow().cmp(key),
            None => core::cmp::Ordering::Less,
        })
        .ok()?;
    by_key.get(pos).copied()
}

//! A validated, acyclic graph and its queries.

use alloc::sync::Arc;
use alloc::vec;
use alloc::vec::Vec;
use core::borrow::Borrow;

use crate::algo::Csr;
use crate::builder::lookup;
use crate::graph::Kept;
use crate::violation::Violations;
use crate::{GraphBuilder, NodeIx, Order, UnknownTargets};

/// A graph proven to have no cycles, with the edges validation kept. Immutable; cheap to clone.
#[derive(Debug, Clone)]
pub struct Dag<K> {
    keys: Arc<[K]>,
    by_key: Arc<[u32]>,
    prerequisites: Arc<Csr>,
    dependents: Arc<Csr>,
    order: Arc<[NodeIx]>,
    rank: Arc<[u32]>,
    by_rank: Arc<[u32]>,
}

/// The layers of a [`Dag`]: layer 0 holds nodes without prerequisites, and a node's layer is one more than its deepest
/// prerequisite's. Nodes in one layer do not depend on each other.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Layers {
    nodes: Vec<NodeIx>,
    bounds: Vec<usize>,
}

impl Layers {
    /// Number of layers.
    #[must_use]
    pub fn len(&self) -> usize {
        self.bounds.len().saturating_sub(1)
    }

    /// Whether there are no layers (the dag is empty).
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.len() == 0
    }

    /// Layer `i`, in the dag's [`Order`].
    #[must_use]
    pub fn get(&self, i: usize) -> Option<&[NodeIx]> {
        let (&start, &end) = (self.bounds.get(i)?, self.bounds.get(i + 1)?);
        self.nodes.get(start..end)
    }

    /// Iterates the layers, first to last.
    pub fn iter(&self) -> impl Iterator<Item = &[NodeIx]> + '_ {
        (0..self.len()).filter_map(|i| self.get(i))
    }
}

impl<K: Ord + Clone> Dag<K> {
    pub(crate) fn new(keys: Arc<[K]>, by_key: Arc<[u32]>, kept: Kept, order: Vec<NodeIx>) -> Self {
        Self {
            keys,
            by_key,
            prerequisites: Arc::new(kept.prerequisites),
            dependents: Arc::new(kept.dependents),
            order: Arc::from(order),
            rank: Arc::from(kept.rank),
            by_rank: Arc::from(kept.by_rank),
        }
    }

    /// Builds and validates in one call, for graphs without edge kinds where an unknown dependency is an error.
    ///
    /// # Errors
    ///
    /// [`Violations`] listing every problem when the nodes do not form a valid dag.
    pub fn from_nodes<I, D>(nodes: I, order: Order) -> Result<Self, Violations<K>>
    where
        I: IntoIterator<Item = (K, D)>,
        D: IntoIterator<Item = K>,
    {
        let nodes = nodes.into_iter();
        let mut b = GraphBuilder::<K>::with_capacity(nodes.size_hint().0);
        for (key, prerequisites) in nodes {
            let node = b.node(key);
            for p in prerequisites {
                b.depends_on(node, p, ());
            }
        }
        b.build(UnknownTargets::Error).validate(order)
    }

    /// Number of nodes.
    #[must_use]
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Whether the dag has no nodes.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    /// The key of node `ix`.
    #[must_use]
    pub fn key(&self, ix: NodeIx) -> Option<&K> {
        self.keys.get(ix.u())
    }

    /// The node at declaration position `position`, for callers that keep per-node data in declaration order. Valid
    /// only for a dag whose graph had no duplicate declarations, which validation guarantees.
    #[must_use]
    pub fn node_at(&self, position: usize) -> Option<NodeIx> {
        if position < self.len() {
            u32::try_from(position).ok().map(NodeIx)
        } else {
            None
        }
    }

    /// The node with `key`.
    pub fn index_of<Q>(&self, key: &Q) -> Option<NodeIx>
    where
        K: Borrow<Q>,
        Q: Ord + ?Sized,
    {
        lookup(&self.keys, &self.by_key, key).map(NodeIx)
    }

    /// The nodes in topological order: the lexicographically smallest valid order under the dag's [`Order`].
    #[must_use]
    pub fn order(&self) -> &[NodeIx] {
        &self.order
    }

    /// The keys in topological order.
    pub fn keys_in_order(&self) -> impl Iterator<Item = &K> + '_ {
        self.order.iter().filter_map(|&ix| self.key(ix))
    }

    /// The nodes `ix` depends on, in the dag's [`Order`]. Empty for an index the dag does not have.
    #[must_use]
    pub fn prerequisites(&self, ix: NodeIx) -> &[NodeIx] {
        self.prerequisites.of(ix.u())
    }

    /// The nodes that depend on `ix`, in the dag's [`Order`]. Empty for an index the dag does not have.
    #[must_use]
    pub fn dependents(&self, ix: NodeIx) -> &[NodeIx] {
        self.dependents.of(ix.u())
    }

    /// The dag's layers. See [`Layers`].
    #[must_use]
    pub fn layers(&self) -> Layers {
        let n = self.len();
        let mut depth = vec![0usize; n];
        for &ix in self.order.iter() {
            let d = self.prerequisites(ix).iter().filter_map(|p| depth.get(p.u())).max().map_or(0, |d| d + 1);
            if let Some(slot) = depth.get_mut(ix.u()) {
                *slot = d;
            }
        }
        let layers = depth.iter().max().map_or(0, |d| d + 1);
        let mut bounds = vec![0usize; layers + 1];
        for &d in &depth {
            if let Some(b) = bounds.get_mut(d + 1) {
                *b += 1;
            }
        }
        for i in 1..bounds.len() {
            let prev = bounds.get(i - 1).copied().unwrap_or(0);
            if let Some(b) = bounds.get_mut(i) {
                *b += prev;
            }
        }
        let mut cursor = bounds.clone();
        let mut nodes = vec![NodeIx(0); n];
        for &i in self.by_rank.iter() {
            let Some(&d) = depth.get(i as usize) else { continue };
            if let Some(c) = cursor.get_mut(d) {
                if let Some(slot) = nodes.get_mut(*c) {
                    *slot = NodeIx(i);
                }
                *c += 1;
            }
        }
        Layers { nodes, bounds }
    }

    /// The nodes that can start now: those for which `eligible(key)` holds and `satisfied(key)` holds for every
    /// prerequisite, in the dag's [`Order`]. One pass over the graph.
    ///
    /// When `satisfied` holds only for nodes that succeeded, a node behind a failure never becomes ready, so direct
    /// prerequisites are enough.
    pub fn ready<'a, S, R>(&'a self, satisfied: S, eligible: R) -> impl Iterator<Item = NodeIx> + 'a
    where
        S: Fn(&K) -> bool + 'a,
        R: Fn(&K) -> bool + 'a,
    {
        self.by_rank.iter().map(|&i| NodeIx(i)).filter(move |&ix| {
            self.key(ix).is_some_and(&eligible)
                && self.prerequisites(ix).iter().all(|&p| self.key(p).is_some_and(&satisfied))
        })
    }

    /// Every node upstream of `roots`, not including the roots, in the dag's [`Order`].
    #[must_use]
    pub fn ancestors(&self, roots: &[NodeIx]) -> Vec<NodeIx> {
        self.closure(roots, &self.prerequisites)
    }

    /// Every node downstream of `roots`, not including the roots, in the dag's [`Order`].
    #[must_use]
    pub fn descendants(&self, roots: &[NodeIx]) -> Vec<NodeIx> {
        self.closure(roots, &self.dependents)
    }

    fn closure(&self, roots: &[NodeIx], next: &Csr) -> Vec<NodeIx> {
        let n = self.len();
        let mut seen = vec![false; n];
        let mut stack: Vec<NodeIx> = Vec::new();
        for r in roots {
            if let Some(s) = seen.get_mut(r.u()) {
                *s = true;
                stack.push(*r);
            }
        }
        let mut found = Vec::new();
        while let Some(ix) = stack.pop() {
            for &m in next.of(ix.u()) {
                if let Some(s) = seen.get_mut(m.u()) {
                    if !*s {
                        *s = true;
                        found.push(m);
                        stack.push(m);
                    }
                }
            }
        }
        found.sort_unstable_by_key(|ix| self.rank.get(ix.u()).copied().unwrap_or(u32::MAX));
        found
    }

    /// Each node's key with its prerequisites' keys, nodes and prerequisites sorted by key, isolated nodes included:
    /// a canonical form of the structure for callers that hash it with their own hasher.
    pub fn canonical(&self) -> impl Iterator<Item = (&K, Vec<&K>)> + '_ {
        self.by_key.iter().filter_map(move |&i| {
            let key = self.keys.get(i as usize)?;
            let mut prerequisites: Vec<&K> =
                self.prerequisites.of(i as usize).iter().filter_map(|&p| self.key(p)).collect();
            prerequisites.sort_unstable();
            Some((key, prerequisites))
        })
    }
}

