/// # Errors
///
/// [`ResumeError::FingerprintMismatch`], [`ResumeError::UnknownStep`] or [`ResumeError::NotAwaitingVerification`],
/// returned before any step runs.
pub async fn resume(prior: &RunRecord, plan: &Plan, opts: &ResumeOptions) -> Result<RunRecord, ResumeError> {
    if prior.plan_fingerprint() != plan.fingerprint() {
        return Err(ResumeError::FingerprintMismatch { record: prior.plan_fingerprint(), plan: plan.fingerprint() });
    }
    if let Some(unknown) = prior.steps().iter().find(|s| plan.index_of(s.step_id()).is_none()) {
        return Err(ResumeError::UnknownStep { step_id: unknown.step_id().clone() });
    }
    // One index instead of a linear `prior.step()` per plan step and per verdict, which made resume O(N²). Every way
    // to build a record (execute, from_parts, deserializing) lists each step once.
    let mut by_id: BTreeMap<&StepId, &StepRecord> = BTreeMap::new();
    for record in prior.steps() {
        by_id.entry(record.step_id()).or_insert(record);
    }
    for step_id in opts.verified.keys() {
        let prev = by_id.get(step_id);
        if !prev.is_some_and(|r| r.awaits_verification()) {
            return Err(ResumeError::NotAwaitingVerification {
                step_id: step_id.clone(),
                status: prev.map_or("missing", |r| r.status().label()),
            });
        }
    }
    let initial = plan
        .steps()
        .iter()
        .map(|step| {
            let Some(&prev) = by_id.get(step.id()) else { return Initial::Run };
            match prev.status() {
                StepStatus::Completed | StepStatus::CompletedEarlier => {
                    Initial::Done(Box::new(carried_over(prev, "completed earlier in this run")))
                }
                StepStatus::OutcomeUnknown(_) | StepStatus::Panicked | StepStatus::Running => {
                    match opts.verified.get(step.id()) {
                        Some(Verification::Applied) => {
                            Initial::Done(Box::new(carried_over(prev, "verified as applied by the caller")))
                        }
                        Some(Verification::NotApplied) => Initial::Run,
                        None if step.runner().replay() == crate::Replay::Idempotent => Initial::Run,
                        None => Initial::Done(Box::new(kept_unresolved(prev))),
                    }
                }
                _ => Initial::Run,
            }
        })
        .collect();
    Ok(scheduler::run(plan, prior.run_id().clone(), &opts.exec, initial).await)
}

/// A prior success, carried into the new record as `CompletedEarlier` with its attempts.
fn carried_over(prev: &StepRecord, reason: &str) -> StepRecord {
    let mut record = StepRecord::new(prev.step_id().clone(), prev.name().to_string(), StepStatus::CompletedEarlier);
    record.reason = Some(reason.to_string());
    record.attempts = prev.attempts().to_vec();
    record
}

/// A prior outcome still in doubt, kept as it was (timing cleared). A step left `Running` by a crash becomes
/// `OutcomeUnknown(Interrupted)`.
fn kept_unresolved(prev: &StepRecord) -> StepRecord {
    let mut record = prev.clone();
    record.started_at = None;
    record.elapsed = None;
    if record.status == StepStatus::Running {
        record.status = StepStatus::OutcomeUnknown(UnknownCause::Interrupted);
        record.error =
            Some(ExecutionError::AmbiguousOutcome { source: Box::new(ExecutionError::Interrupted { elapsed_ms: 0 }) });
        record.reason =
            Some("in flight when the previous process stopped; verify whether it took effect, then resume".to_string());
    }
    record
}

//! Change 5: resume continues a run from its record under the same run id, never re-runs finished steps, and
//! respects ambiguity.

mod common;

use std::sync::atomic::Ordering;
use std::sync::{Arc, Mutex};
use std::time::Duration;

use common::*;
use michi_pipeline::{
    execute, resume, BreakerConfig, BreakerRegistry, CancellationToken, ExecOptions, ResumeError, ResumeOptions, RunId,
    RunOutcome, RunRecord, SkipReason, StepObserver, StepRecord, StepStatus, UnknownCause, Verification,
};

#[tokio::test(start_paused = true)]
async fn resume_reruns_only_what_did_not_succeed_under_the_same_run_id_and_idempotency_keys() {
    let log = Log::new();
    let a = Scripted::new(&log, "a", vec![Act::Ok]);
    let b = Scripted::new(&log, "b", vec![Act::Err(fatal("first time")), Act::Ok]);
    let (a_calls, b_calls, b_keys) = (Arc::clone(&a.calls), Arc::clone(&b.calls), Arc::clone(&b.keys));
    let p = plan(vec![exec("a", &[], a), exec("b", &["a"], b), act(&log, "c", &["b"], Act::Ok)]);
    let first = execute(&p, rid("run-9"), &ExecOptions::new()).await;
    assert_eq!(first.outcome(), RunOutcome::Failed);

    let second = resume(&first, &p, &ResumeOptions::default()).await.unwrap();
    assert_eq!(second.run_id().as_str(), "run-9");
    assert_eq!(a_calls.load(Ordering::SeqCst), 1, "a completed before and is never re-run");
    assert_eq!(b_calls.load(Ordering::SeqCst), 2);
    assert_eq!(
        statuses(&second),
        [
            ("a".into(), StepStatus::CompletedEarlier),
            ("b".into(), StepStatus::Completed),
            ("c".into(), StepStatus::Completed),
        ]
    );
    assert_eq!(second.outcome(), RunOutcome::Succeeded);
    assert_eq!(*b_keys.lock().unwrap(), ["run-9:b", "run-9:b"], "the key is stable across resume");
    assert_eq!(second.completion_order(), &[sid("b"), sid("c")], "carried-over steps are not in this run's order");

    let third = resume(&second, &p, &ResumeOptions::default()).await.unwrap();
    assert!(third.steps().iter().all(|s| s.status() == StepStatus::CompletedEarlier));
    assert_eq!(third.outcome(), RunOutcome::Succeeded);
}

