use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use michi_pipeline::{execute, resume, step_fn, ExecOptions, ExecStep, Plan, ResumeOptions, RunId, RunRecord, StepId, StepObserver, StepRecord};

struct FailedStore;
impl StepObserver for FailedStore {
    fn on_step_started(&self, _: &RunId, _: &StepId) { panic!("in-flight save failed"); }
    fn on_step_finished(&self, _: &RunId, _: &StepRecord) {}
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let commits = Arc::new(AtomicUsize::new(0));
    let counter = Arc::clone(&commits);
    let step = ExecStep::new(StepId::try_new("charge").unwrap(), "Charge", step_fn(move |_| {
        let counter = Arc::clone(&counter);
        async move { counter.fetch_add(1, Ordering::SeqCst); Ok(()) }
    }));
    let plan = Plan::new(vec![step]).unwrap();
    let run_id = RunId::try_new("r").unwrap();
    let first = execute(&plan, run_id.clone(), &ExecOptions::new().observer(Arc::new(FailedStore))).await;
    assert_eq!(first.observer_panics(), 1);
    assert_eq!(commits.load(Ordering::SeqCst), 1);
    // A process crash before the returned record is durably saved leaves no observer records.
    let recovered = RunRecord::from_parts(run_id, plan.fingerprint(), &plan, vec![]).unwrap();
    let second = resume(&recovered, &plan, &ResumeOptions::default()).await.unwrap();
    assert_eq!(second.steps().len(), 1);
    assert_eq!(commits.load(Ordering::SeqCst), 2);
    println!("observer_panics={}, commits_after_resume={}", first.observer_panics(), commits.load(Ordering::SeqCst));
}

