use std::collections::BTreeSet;
use michi_pipeline::{step_fn, ExecStep, Plan, StepId};

fn next(state: &mut u64) -> u64 {
    *state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    *state
}

fn main() {
    let mut state = 0x7a9c_3391_1288u64;
    for case in 0..1000 {
        let n = 12usize;
        let mut declaration: Vec<usize> = (0..n).collect();
        for i in (1..n).rev() { declaration.swap(i, next(&mut state) as usize % (i + 1)); }
        let mut deps = vec![Vec::<usize>::new(); n];
        for i in 0..n {
            for p in 0..i {
                if next(&mut state) % 4 == 0 { deps[i].push(p); }
            }
        }
        let make_plan = |decl: &[usize]| {
            let steps = decl.iter().map(|&i| {
                let mut s = ExecStep::new(StepId::try_new(format!("s{i}")).unwrap(), "x", step_fn(|_| async { Ok(()) }));
                for &p in &deps[i] { s = s.depends_on(StepId::try_new(format!("s{p}")).unwrap()); }
                s
            }).collect();
            Plan::new(steps).unwrap()
        };
        let plan = make_plan(&declaration);
        let mut remaining: Vec<usize> = declaration.iter().map(|&i| deps[i].len()).collect();
        let mut ready: BTreeSet<usize> = (0..n).filter(|&ix| remaining[ix] == 0).collect();
        let mut expected = Vec::new();
        while let Some(ix) = ready.pop_first() {
            let id = declaration[ix];
            expected.push(format!("s{id}"));
            for d in 0..n {
                if deps[declaration[d]].contains(&id) {
                    remaining[d] -= 1;
                    if remaining[d] == 0 { ready.insert(d); }
                }
            }
        }
        let got: Vec<String> = plan.execution_order().iter().map(ToString::to_string).collect();
        assert_eq!(got, expected, "case {case}");
        declaration.reverse();
        assert_eq!(plan.fingerprint(), make_plan(&declaration).fingerprint(), "case {case}");
