use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;

use michi_pipeline::{execute, resume, step_fn, ExecOptions, ExecStep, ExecutionError, Plan, ResumeOptions, RunId, StepId};

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let commits = Arc::new(AtomicUsize::new(0));
    let counter = Arc::clone(&commits);
    let step = ExecStep::new(StepId::try_new("charge").unwrap(), "Charge", step_fn(move |_| {
        let counter = Arc::clone(&counter);
        async move {
            counter.fetch_add(1, Ordering::SeqCst);
            Err(ExecutionError::Failed { message: "committed, then failed".into(), retryable: false })
        }
    }));
    let plan = Plan::new(vec![step]).unwrap();
    let first = execute(&plan, RunId::try_new("r").unwrap(), &ExecOptions::new()).await;
    assert_eq!(first.steps()[0].attempts().len(), 1);
    assert!(!first.steps()[0].error().unwrap().is_retryable());
    let second = resume(&first, &plan, &ResumeOptions::default()).await.unwrap();
    assert_eq!(second.steps()[0].attempts().len(), 1);
    assert_eq!(commits.load(Ordering::SeqCst), 2);
    println!("first_status={:?}, retryable={}, commits_after_resume={}", first.steps()[0].status(), first.steps()[0].error().unwrap().is_retryable(), commits.load(Ordering::SeqCst));
}

